function looksLikePidDescription(text){return /p\s*&\s*id|p\s*and\s*id|\bpid\b|piping\s+(?:and|&)\s+instrument(?:ation)?|process\s+(?:and|&)\s+instrument(?:ation)?|\bprocess\s+drawing\b|\bflowsheet\b/i.test(String(text||''));}
