        ...((attachment && attachment.fileId) || webResearchRequested ? { 'anthropic-beta': [attachment && attachment.fileId ? 'files-api-2025-04-14' : null, webResearchRequested ? 'web-search-2025-03-05' : null].filter(Boolean).join(',') } : {}),

