selectKnowledge=function(message,context,mode){
 const out=previousSelectKnowledge12KE(message,context,mode),q=String(message||'');
 if(/reciproc|crosshead|rod.?reversal|pulsation|snubber|prime.?mover|torque.?speed|motor.*(?:slip|start|pole|power.?factor)|engine.?start|13[- ](?:4[1-9]|50)|24[- ]4[1-9]/i.test(q))out.reciprocatingSourceDelta12KE=PETROSKILLS_DELTA_12KE.reciprocating;
 if(/phase|bubble.?point|dew.?point|criconden|retrograde|triple.?point|critical.?point|reservoir|flash.*(?:separ|composition|envelope)|fractionat|4[- ](?:[3-9]|1[0-8])\b/i.test(q))out.phaseSourceDelta12KE=PETROSKILLS_DELTA_12KE.phase;
 if(/(?:F[- ]?(?:1050|1055|5015|5016))\b|758054|770493|57058|filter.*(?:plate|serial|tag|model|rating)/i.test(q))out.filterPlateUpdate12KE=FILTER_PLATE_UPDATE_12KE;
 if(/nameplate|data[ -]?plate|plate (?:audit|photo|picture)|missing (?:plate|serial)/i.test(q)){
  out.nameplateAudit12KE=NAMEPLATE_AUDIT_UPDATE_12KE;
  if(out.nameplateAudit12KB)out.nameplateAudit12KB=Object.assign({},out.nameplateAudit12KB,{historicalBaseline:true,currentUpdate:'Use retained12KD slug update and12KE filter update; no other audit identities declared complete.'});
 }
 return out;
};
