const NAMEPLATE_AUDIT_UPDATE_12KF={"build":"12KF","baseline":"12KE","currentRecord":{"id":"plate_e5000","tag":"E-5000","category":"Vessel / equipment","area":"Stabilizer / overhead","assetIds":["e5000"],"aliases":[],"service":"Inlet preheater - process tube / hot-oil shell","parent":["E-5000"],"status":"PLATE_TRANSCRIPTION_RETAINED","priority":3,"tagConfirmed":true,"referenceOnly":false,"retained":["Visible equipment tag: E-5000","Manufacturer: Southern Heat Exchanger Corporation","Marked location: Tuscaloosa, Alabama","National Board number: 15582","SHECO serial number: 19-0239","Customer order: 50373-64011","Year built: 2020","Shell - internal MAWP: 300 psig at 400 F","Shell - MDMT: -20 F at 300 psig","Tube - internal MAWP: 720 psig at 400 F","Tube - MDMT: -20 F at 720 psig","Shell and tube - external MAWP: Each row is stamped XXXX PSIG at XXXX F; no numeric external/vacuum rating established","Visible certification markings: Certification stamp with U and W; no additional code edition or stamp meaning inferred"],"evidence":["IMG_0693.jpeg - visible CUST. ITEM E-5000 with serial19-0239 and NB15582; shell and tube ratings transcribed separately."],"photoIds":["IMG_0693.jpeg"],"missing":["Manufacturer mechanical data sheet / general-arrangement and nozzle drawing for dimensions, materials, tube count/pass arrangement and any corrosion allowance or hydrotest information not printed on this plate.","External-pressure/vacuum capability requires a controlled manufacturer/design record when needed; the XXXX fields are not a zero value or a full-vacuum rating.","Relief-device settings, allowable shell-to-tube differential pressure and current operating limits require their own approved records; they are not established by these two side ratings."],"conflicts":[],"drawings":["020185-AE-DW-M2500"],"source":["IMG_0693.jpeg - 12KF installed-plate review"],"sourceRecords":1,"basis":"Existing 12KB model inventory with cumulative photo reviews through12KF; not a new field inspection or certified relief/pressure-system assessment.","historyBefore12KF":{"id":"plate_e5000","tag":"E-5000","category":"Vessel / equipment","area":"Stabilizer / overhead","assetIds":["e5000"],"aliases":[],"service":"Inlet preheater - process tube / hot-oil shell","parent":["E-5000"],"status":"NO_ASSIGNED_INSTALLED_PLATE","priority":3,"tagConfirmed":true,"referenceOnly":false,"retained":[],"evidence":[],"photoIds":[],"missing":["Both shell-side and tube-side pressure/temperature ratings, or separately stamped side plates, as applicable.","Equipment identity/rating plate (manufacturer/model/serial; vessel MAWP/MDMT/design temperature/NB as applicable), tagged wide view and available general-arrangement/nozzle drawing. Separate driver plate where fitted."],"conflicts":[],"drawings":["020185-AE-DW-M2500"],"source":[],"sourceRecords":1,"basis":"Retained source/model inventory; not field inspection or a certificate of absent field nameplates."},"latestReviewBuild":"12KF"},"summary":{"auditRows":690,"categories":{"Control / regulating valve":234,"ESD / shutdown valve":54,"PSV / relief":90,"Vessel / equipment":312},"statuses":{"IDENTITY_CONFLICT":7,"NO_ASSIGNED_INSTALLED_PLATE":612,"IDENTITY_OR_SETTING_CONFLICT":2,"PARTIAL_PLATE_RECORD":19,"PLATE_TRANSCRIPTION_RETAINED":15,"LEGACY_PLATE_REFERENCE":8,"ACCESSORY_OR_SHARED_PLATE_ONLY":6,"ASSEMBLY_TAG_PENDING":13,"NONCODED_ASSEMBLY_REFERENCE":5,"LEGACY_RATING_REFERENCE":3},"referenceOnlyRows":213,"componentRowsExcluded":6259,"retainedPhotoLinksRestored":12},"collectionOrder":"Control valves, ESD/shutdown valves and vessels/equipment first; regulators, manual valves and remaining components later. No other plate or PSV gap is closed by this update.","scope":"One new E-5000 plate review; no new whole-facility scan and no other identity completion."};
