selectKnowledge=function(message,context,mode){
 const out=previousSelectKnowledge12KF(message,context,mode),q=String(message||'');
 if(/mass.?transfer|fractionat|stabili[sz]|absorp|stripp|reflux|reboil|condenser|tray|downcomer|weir|HETP|relative.?volatil|packed.?tower|random.?packing|structured.?packing|14[- ](?:[3-9]|1[0-9]|2[0-2])\b/i.test(q))out.massTransferSourceDelta12KF=PETROSKILLS_DELTA_12KF.massTransfer;
 if(/\bpumps?\b|centrifugal|impeller|NPSH|low.flow.?recycle|vapor.?lock|positive.?displacement|septuplex|triplex|quintuplex|liquid.?ring|11[- ](?:2[6-9]|3[0-7])\b/i.test(q))out.pumpSourceDelta12KF=PETROSKILLS_DELTA_12KF.pumps;
 if(/\bE[- ]?5000\b|\b15582\b|19[- ]0239|50373[- ]64011|Southern.*(?:exchanger|plate)/i.test(q)){
  out.e5000Nameplate12KF=E5000_NAMEPLATE_12KF;
  out.e5000PlateAudit12KF=NAMEPLATE_AUDIT_UPDATE_12KF;
 }
 if(/nameplate|data[ -]?plate|plate (?:audit|photo|picture)|missing (?:plate|serial)/i.test(q))out.nameplateAudit12KF=NAMEPLATE_AUDIT_UPDATE_12KF;
 return out;
};
