 var rows=cfAlarmRows12MG(key).filter(function(r){return r.kind===phase+'-permissive';}),checks=rows.map(function(r){var reading=cfAlarmReading12MG(r,c,{},0),status=cfAlarmClassify12MG(r,reading.value);return {id:r.id,label:r.parameter,minimum:r.limits.LL,unit:r.unit,value:reading.value,basis:reading.basis,status:status,ok:status==='PERMISSIVE_MET'};});
 return {ok:checks.every(function(c){return c.ok;}),checks:checks,scope:'Supplied named permissives only; not a complete validated plant startup sequence.'};
