Object.assign(RYAN_INDEX_REFERENCE_12JT.summary,{sourceDefinitions:RYAN_INDEX_REFERENCE_12JT.sourceDefinitions.length,sourceDefinitionBlocks:RYAN_INDEX_REFERENCE_12JT.sourceDefinitions.length,referenceNotes:Object.keys(RYAN_INDEX_REFERENCE_12JT.referenceNotes).length,latestUpdate:'12MG',sourceIndexBuild:'12MG',quizQuestions:368,newQuizQuestions:24,update12MG:RYAN_INDEX_MANIFEST_12JT.update12MG});
