//12NG: site-authenticated shared question journal. Existing AI authorization/provider logic stays inside the original handler.
const RYAN_SHARED_SERVICE_12NG=require('../lib/ryan-shared.cjs');
const RYAN_HANDLER_BEFORE_12NG=exports.handler;
const RYAN_SHARED_12NG=RYAN_SHARED_SERVICE_12NG.createService();
exports.handler=async function(event){
 let body;try{body=event.httpMethod==='POST'?JSON.parse(event.isBase64Encoded?Buffer.from(event.body||'','base64').toString('utf8'):event.body||'{}'):{};}catch{return RYAN_HANDLER_BEFORE_12NG(event);}
 if(body&&body.sharedHistoryAction){try{return await RYAN_SHARED_12NG.action(event,RYAN_SHARED_SERVICE_12NG.parse(event));}catch(e){return RYAN_SHARED_SERVICE_12NG.response(e.statusCode||503,{error:e.statusCode?e.message:'Shared history is temporarily unavailable. No confirmed shared save.',code:e.code||'SHARED_UNAVAILABLE',buildId:RYAN_BUILD_ID});}}
 const mode=String(body&&body.mode||'qa').toLowerCase(),eligible=body&&typeof body.message==='string'&&body.message.trim()&&!/^(auth|health|reference_search|digest(?:_|$)|image_learn|operating_memory_extract|shift_report_chunk)/.test(mode);
 if(!eligible)return RYAN_HANDLER_BEFORE_12NG(event);
 const expected=normalizeRyanSecret(process.env.RYAN_AI_PASSWORD||process.env.RYAN_PASSWORD||'');
 if(!verifyRyanAuthToken(body.authToken,ryanAuthSigningSecret())&&!ryanPasswordAccepted(body.password,expected))return RYAN_HANDLER_BEFORE_12NG(event);
 if(body.clientBuild&&body.clientBuild!==RYAN_BUILD_ID)return RYAN_HANDLER_BEFORE_12NG(event);
 if(!body.sharedQuestionId)body.sharedQuestionId=Date.now()+'-'+require('node:crypto').randomUUID();
 let job;try{job=await RYAN_SHARED_12NG.begin(event,body);}catch(e){return RYAN_SHARED_SERVICE_12NG.response(e.statusCode||503,{error:e.statusCode?e.message:'Shared question storage is unavailable. No new AI request was sent; retry when storage is restored.',code:e.code||'SHARED_UNAVAILABLE',buildId:RYAN_BUILD_ID});}
 if(job.duplicate){const d=job.duplicate;if(d.status==='complete')return RYAN_SHARED_SERVICE_12NG.response(200,{reply:d.record.answer,workplan:d.record.workplan,buildId:RYAN_BUILD_ID,codeSignature:RYAN_CODE_SIGNATURE,cost:{usd:0},sharedHistory:{id:job.id,saved:true,status:'complete',requestAlreadyCompleted:true}});return RYAN_SHARED_SERVICE_12NG.response(409,{error:'This question is already saved as '+d.status+'. Check Questions Asked; a duplicate AI request was not sent.',buildId:RYAN_BUILD_ID,sharedHistory:{id:job.id,saved:true,status:d.status}});}
 let result;try{result=await RYAN_HANDLER_BEFORE_12NG(event);}catch{result=RYAN_SHARED_SERVICE_12NG.response(500,{error:'Ryan request failed.',buildId:RYAN_BUILD_ID});}
 return RYAN_SHARED_12NG.finish(job,body,result);
};
module.exports.SHARED_HISTORY_12NG={service:RYAN_SHARED_12NG,previousHandler:RYAN_HANDLER_BEFORE_12NG};

